package com.aigora.tutororchestrator.application.usecase;
import com.aigora.tutororchestrator.application.contracts.command.*; import com.aigora.tutororchestrator.application.error.*; import com.aigora.tutororchestrator.application.ports.*; import com.aigora.tutororchestrator.application.contracts.result.*; import com.aigora.tutororchestrator.domain.model.*; import com.aigora.tutororchestrator.domain.valueobjects.SessionVersion; import java.time.*;
public final class StartLearningSessionUseCase {
 private final LearningSessionRepository repo; private final SessionEventPublisher publisher; private final LifecycleTelemetrySink telemetry; private final Clock clock;
 public StartLearningSessionUseCase(LearningSessionRepository repo, SessionEventPublisher publisher, LifecycleTelemetrySink telemetry, Clock clock){this.repo=repo;this.publisher=publisher;this.telemetry=telemetry;this.clock=clock;}
 public SessionResult<LearningSession> execute(StartLearningSessionCommand c){long started=System.nanoTime(); var existing=repo.findById(c.sessionId()); if(existing.isPresent()){if(existing.get().hasProcessed(c.commandId())){telemetry.record("start",c.sessionId(),existing.get().version(),"deduplicated",System.nanoTime()-started);return new SessionSuccess<>(existing.get());}return fail(c,SessionErrorCode.SESSION_ALREADY_EXISTS,"Learning session already exists",started,existing.get().version());} try {var session=LearningSession.create(c.sessionId(),c.studentId(),Instant.now(clock));session.start(c.initialNodeId(),c.initialExerciseId(),c.commandId(),c.correlationId(),c.causationId(),Instant.now(clock));var events=session.drainEvents();repo.insert(session);try{publisher.publish(events);}catch(RuntimeException e){return fail(c,SessionErrorCode.EVENT_PUBLICATION_FAILURE,e.getMessage(),started,session.version());}telemetry.record("start",session.id(),session.version(),"success",System.nanoTime()-started);return new SessionSuccess<>(session.copy());}catch(RuntimeException e){return fail(c,SessionErrorCode.INVALID_TRANSITION,e.getMessage(),started,SessionVersion.NEW);}}
 private SessionResult<LearningSession> fail(StartLearningSessionCommand c,SessionErrorCode code,String msg,long started,SessionVersion version){telemetry.record("start",c.sessionId(),version,"failure:"+code,System.nanoTime()-started);return UseCaseSupport.failure(code,msg==null?code.name():msg);}
}
